    public static int run()throws Exception{
        assertions=0;check(VECTORS.length>0,"Native effects vectors present");Owner last=null;
        for(String vector:VECTORS){DataInputStream in=new DataInputStream(new InflaterInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(vector))));String name=in.readUTF();boolean pixels=in.readBoolean();int loadHandle=in.readInt();Map<Integer,int[][]> writes=new HashMap<>();for(int n=in.readInt();n>0;n--){int mask=in.readInt();int[][] w=new int[in.readInt()][];for(int k=0;k<w.length;k++)w[k]=ints(in);writes.put(mask,w);}Map<String,int[][]> spriteWrites=new HashMap<>();for(int n=in.readInt();n>0;n--){String key=in.readUTF();int[][] w=new int[in.readInt()][];for(int k=0;k<w.length;k++)w[k]=ints(in);spriteWrites.put(key,w);}boolean realEffects=in.readBoolean(),partialPixels=in.readBoolean();Owner owner=new Owner(snapshot(in),pixels,loadHandle,writes,spriteWrites,realEffects,partialPixels);last=owner;String error=null;for(int n=in.readInt();n>0;n--){String kind=in.readUTF();int[] a=ints(in);if(error==null)try{owner.operation(kind,a);}catch(IOException failure){error=failure.getMessage();}}Snapshot expected=snapshot(in);String nativeError=in.readUTF();check(nativeError.isEmpty()?error==null:error!=null,"Exact native known owner boundary "+name+" "+error);owner.compare(expected,name);}
        Dc2PartialRedraw missing=new Dc2PartialRedraw(last,last.compositor,null);last.writeInt(Dc2RainPipeline.PENDING,1);missing.redraw(255,0,0,80,90);check(true,"Suppressed dispatcher needs no leaf");last.writeInt(Dc2RainPipeline.PENDING,0);missing.redraw(1,0,0,80,90);check(true,"Background-only partial redraw needs no fake UI/effect leaf");boolean rejected=false;try{missing.redraw(2,0,0,80,90);}catch(IOException exact){rejected=exact.getMessage().contains("411c20");}check(rejected,"Active effect consumer missing is precise error");return assertions;
    }
    public static void main(String[] args)throws Exception{System.out.println("DC2 partial redraw assertions: "+run());}
